export function ventilationReminder(cpr=false){return `<aside class="ventilation-reminder" aria-label="Avoid overventilation"><strong>You are probably bagging <em>TOO HARD</em> and <em>TOO FAST.</em></strong><b>Slow down. Count breaths.</b><p>Overventilation reduces blood flow and can cause gastric inflation, vomiting / aspiration.</p>${cpr?'<p class="ventilation-rosc"><b>During CPR, overventilation reduces coronary perfusion and the chance of ROSC.</b></p>':''}</aside>`;}
